#include "typed_tensor.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
namespace penta::runtime::detail {
std::size_t tensorElements(std::span<const std::size_t> shape,std::size_t maximum){if(shape.empty()||shape.size()>8)throw TensorError(1,"Typed tensors have rank1..8.");std::size_t count=1;for(const auto extent:shape){if(!extent||extent>maximum||count>maximum/extent)throw TensorError(7,"Typed tensor positive shape exceeds its element allowance.");count*=extent;}return count;}
std::size_t TensorData::coefficientWidth()const{switch(entryType){case language::Type::Real:return 1;case language::Type::Complex:return 2;case language::Type::Pentarnion:return 5;case language::Type::Element:if(algebra)return algebra->dimension();break;default:break;}throw TensorError(1,"Tensor entries require explicit real/complex/Pentarnion/immutable algebra types.");}
std::size_t TensorData::elements()const{return tensorElements(shape);}
std::size_t TensorData::linearIndex(std::span<const std::size_t> indices)const{const auto count=elements();if(indices.size()==1){if(indices[0]>=count)throw TensorError(1,"Linear tensor index exceeds its shape.");return indices[0];}if(indices.size()!=shape.size())throw TensorError(1,"A tensor index supplies every dimension or one linear index.");std::size_t index=0,stride=1;for(std::size_t dimension=0;dimension<shape.size();++dimension){if(indices[dimension]>=shape[dimension])throw TensorError(1,"Tensor index exceeds its declared dimension.");index+=indices[dimension]*stride;stride*=shape[dimension];}return index;}
std::size_t TensorData::retainedBytes()const noexcept{return sizeof(TensorData)+shape.capacity()*sizeof(std::size_t)+values.capacity()*sizeof(double);}
bool sameTensorDescriptor(const TensorData& a,const TensorData& b)noexcept{if(a.entryType!=b.entryType||a.shape!=b.shape)return false;if(a.entryType==language::Type::Pentarnion)return a.gamma==b.gamma;if(a.entryType==language::Type::Element)return a.algebra&&b.algebra&&a.algebra->hash()==b.algebra->hash();return true;}
TensorValue makeTensor(language::Type entryType,algebra::universal::DefinitionPtr algebra,double gamma,std::vector<std::size_t> shape,std::vector<double> values,const TensorLimits& limits,const std::atomic_bool* cancellation){auto result=std::make_shared<TensorData>();result->entryType=entryType;result->algebra=std::move(algebra);result->gamma=gamma;result->shape=std::move(shape);const auto width=result->coefficientWidth(),count=tensorElements(result->shape,std::min<std::size_t>(1000000,limits.elements));if(!width||width>64||count>std::min<std::size_t>(8000000,limits.coordinates)/width||values.size()!=count*width)throw TensorError(7,"Typed tensor packing exceeds its exact full-coordinate shape/allowance.");if(!std::isfinite(gamma)||(entryType==language::Type::Pentarnion&&(gamma<0||gamma>1)))throw TensorError(1,"Legacy tensor algebra parameter is invalid.");if(entryType!=language::Type::Element&&result->algebra)throw TensorError(1,"Only generic tensor entries carry an immutable algebra descriptor.");result->values=std::move(values);if(result->retainedBytes()>limits.bytes)throw TensorError(7,"Typed tensor retained allocation exceeds its memory allowance.");for(std::size_t at=0;at<result->values.size();++at){if((at&4095u)==0&&cancellation&&cancellation->load())throw TensorError(3,"Typed tensor construction cancelled.");if(!std::isfinite(result->values[at]))throw TensorError(2,"Tensor coefficients must be finite.");}return result;}
}
